class Msicons extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"})}async connectedCallback(){await this.loadAndRenderSVG()}async loadAndRenderSVG(){try{await Promise.resolve();const t=this.getAttributes();if(!t.icon)return void this.renderError();const n=await fetch(`/icons/${t.icon}.svg`);if(!n.ok)throw new Error(`Failed to load icon: ${t.icon}`);const e=await n.text();this.renderComponent(t,e),this.hasAttribute("disabled")&&this.disable()}catch(t){console.error("Error loading SVG:",t),this.renderError()}}getAttributes(){return{icon:this.getAttribute("icon"),color:this.getAttribute("color")||"var(--psfx-texto-color)",hoverColor:this.getAttribute("hover-color")||"var(--psfx-texto-color)",disabledColor:this.getAttribute("disabled")||"var(--psfx-ui-slider-circular-disabled-color)",size:this.getAttribute("size")||"40px"}}renderComponent(t,n){this.shadowRoot.innerHTML=`\n      <style>\n        :host {\n          display: inline-block;\n          width: ${t.size};\n          height: ${t.size};\n        }\n        \n        .ps-btn-icon {\n          width: 100%;\n          height: 100%;\n          display: flex;\n          justify-content: center;\n          align-items: center;\n        }\n  \n        .ps-btn-icon svg {\n          width: 100% !important;\n          height: 100% !important;\n          fill: ${t.color} !important;\n          transition: fill 0.2s ease;\n        }\n  \n        /* Correção do hover-color */\n        .ps-btn-icon:hover svg {\n          fill: ${t.hoverColor} !important;\n        }\n  \n        :host([disabled]) .ps-btn-icon svg {\n          fill: ${t.disabledColor} !important;\n          pointer-events: none;\n        }\n      </style>\n      <div class="ps-btn-icon">${n}</div>\n    `}renderError(){const t=this.getAttribute("size")||"40px";this.shadowRoot.innerHTML=`\n      <style>\n        :host {\n          display: inline-block;\n          width: ${t};\n          height: ${t};\n        }\n        .error-icon {\n          width: 100%;\n          height: 100%;\n          fill: #999;\n        }\n      </style>\n      <svg class="error-icon" viewBox="0 0 24 24">\n        <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/>\n      </svg>\n    `}disable(){this.shadowRoot.querySelector(".ps-btn-icon")&&this.setAttribute("disabled","")}enable(){this.shadowRoot.querySelector(".ps-btn-icon")&&this.removeAttribute("disabled")}static get observedAttributes(){return["disabled","color","hover-color","size","icon"]}attributeChangedCallback(t,n,e){n!==e&&this.loadAndRenderSVG()}}customElements.define("ms-icon",Msicons);